chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"claude-clean-selection",title:"Clean with Claude Clean",contexts:["selection"],documentUrlPatterns:["https://claude.ai/*"]})});chrome.contextMenus.onClicked.addListener(e=>{e.menuItemId==="claude-clean-selection"&&e.selectionText&&chrome.storage.local.set({incomingText:e.selectionText})});chrome.runtime.onMessage.addListener((e,o,n)=>{if(e.action==="getIncomingText")return chrome.storage.local.get("incomingText",c=>{const t=c.incomingText||"";t&&chrome.storage.local.remove("incomingText"),n({text:t})}),!0});
